import {uid,money,projectClient,invoiceStatus,defaultPlan,saveClient,archiveClient,updateProject,archiveProject,reopenProject,saveProposal,publishProposal,reviseProposal,acceptProposal,declineProposal,approveMilestone,togglePhase,saveIntake,submitInquiry} from './domain.js';

export function createJourneyUI(ctx){
 const {getState:S,open,btn,icon,esc,badge,avatar,date,save,render,toast,dialog}=ctx;
 const project=id=>S().projects.find(p=>p.id===id);
 const commit=message=>{save();render();if(message)toast(message);};
 const field=(label,name,value='',extra='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const note=text=>`<div class="notice">${text}</div>`;
 const err='<div class="form-error" role="alert"></div>';
 let phaseIds=[];
 function projectDetail(id){
  const s=S(),p=project(id),c=projectClient(s,p),bills=s.invoices.filter(i=>i.projectId===id),hours=s.time.filter(t=>t.projectId===id).reduce((a,t)=>a+t.hours,0);
  const canDeliver=!p.archived&&['active','completed'].includes(p.status);
  open('Project',`<div class="dialog-body"><div class="detail-client">${avatar(c)}${esc(c.name)} ${badge(p.archived?'archived':p.status)}</div><h1>${esc(p.name)}</h1><p>${esc(p.service)} · ${p.due?'Target '+date(p.due):'No target date'}</p><div class="action-row">${!p.archived&&p.status!=='cancelled'?btn('Edit project','edit-project',`data-id="${id}"`):''}${p.status==='cancelled'&&!p.archived?btn('Reopen project','reopen-project',`data-id="${id}"`):''}${btn(p.archived?'Restore project':'Archive','archive-project',`data-id="${id}"`)}</div><div class="summary-grid"><div><small>Project fee</small><strong>${p.needsPricing?'Not set':money(p.budget)}</strong></div><div><small>Collected</small><strong>${money(bills.reduce((a,i)=>a+i.paid,0))}</strong></div><div><small>Time tracked</small><strong>${hours.toFixed(1)} h</strong></div></div>
  ${p.inquiry?`<section class="section"><h3>Inquiry</h3><p class="readable">${esc(p.inquiry.scope)}</p>${p.inquiry.answer?`<p class="muted">${esc(p.inquiry.question)}<br>${esc(p.inquiry.answer)}</p>`:''}<span class="badge">${esc(p.inquiry.tag)}</span></section>`:''}
  <section class="section"><div class="section-heading"><h3>Proposal</h3>${badge(p.proposalStatus)}</div><p class="hint">${p.accepted?'Accepted terms are locked.':p.proposalStatus==='published'?'A published version is ready for client review.':'Set the scope, deliverables, fee, phases, and billing schedule.'}</p><div class="action-row">${btn(p.proposalStatus==='draft'?'Edit proposal':'View proposal','proposal',`data-id="${id}"`,'primary')}${p.currentVersion?btn('Client preview','proposal-client',`data-id="${id}" data-version="${p.currentVersion}"`):''}</div></section>
  <section class="section"><h3>Delivery phases</h3>${p.phases.map((f,i)=>{const rules=p.billingPlan.filter(r=>r.phaseId===f.id),amount=rules.reduce((a,r)=>a+r.amount,0);return `<div class="phase-row"><span class="phase-check ${f.done?'done':''}">${f.done?icon('check'):i+1}</span><span class="phase-label">${esc(f.name)}${rules.length?`<small>${money(amount)} on approval</small>`:''}</span>${rules.length?(f.approved?'<span class="badge active">Approved</span>':btn('Approve','approve-preview',`data-id="${id}" data-phase="${f.id}" ${canDeliver?'':'disabled'}`)):btn(f.done?'Reopen':'Complete','complete-phase',`data-id="${id}" data-phase="${f.id}" ${canDeliver?'':'disabled'}`)}</div>`;}).join('')}${!canDeliver?'<p class="hint">Delivery actions are available after the deposit is paid.</p>':''}</section>
  <section class="section"><h3>Billing schedule</h3>${schedule(p,bills)}${p.accepted&&p.billingPlan.some(r=>!r.phaseId)&&!bills.some(i=>i.kind==='deposit')&&!p.archived&&p.status!=='cancelled'?btn('Create deposit invoice','deposit',`data-id="${id}"`):''}<div class="list-line"><span class="muted">Total invoiced</span><strong>${money(bills.reduce((a,i)=>a+i.amount,0))}</strong></div></section><div class="action-row">${btn(icon('clock')+'Log time','log-time',`data-id="${id}"`)}${btn('Client portal preview','portal',`data-id="${id}"`)}</div></div>`,{drawer:true});
 }
 function schedule(p,bills=[]){return p.billingPlan.length?p.billingPlan.map(r=>{const i=bills.find(i=>i.ruleId===r.id);return `<div class="billing-line"><span><strong>${esc(r.name)}</strong><small>${r.phaseId?'On approval: '+esc(p.phases.find(f=>f.id===r.phaseId)?.name||'Milestone'):'On proposal acceptance'}</small></span><span class="billing-amount">${money(r.amount)}${i?`<button class="text-btn" data-action="invoice" data-id="${i.id}">${i.number} · ${invoiceStatus(i)}</button>`:'<small>Scheduled</small>'}</span></div>`;}).join(''):'<p class="muted">Set the project fee and billing schedule in the proposal.</p>';}
 function clientDetail(id){const s=S(),c=s.clients.find(c=>c.id===id);open('Client',`<div class="dialog-body"><div class="detail-client">${avatar(c)}${esc(c.tag)} ${c.archived?badge('archived'):''}</div><h1>${esc(c.name)}</h1><p>${esc(c.contact)} · ${esc(c.email)}</p><div class="action-row">${btn('Edit client','edit-client',`data-id="${id}"`)}${btn(c.archived?'Restore client':'Archive','archive-client',`data-id="${id}"`)}</div><section class="section"><h3>Projects</h3>${s.projects.filter(p=>p.clientId===id).map(p=>`<button class="list-line full-width" data-action="project" data-id="${p.id}"><span>${esc(p.name)}</span>${badge(p.archived?'archived':p.status)}</button>`).join('')||'<p class="muted">No projects yet.</p>'}</section>${!c.archived?`<div class="action-row">${btn(icon('plus')+'New project','new-project',`data-client="${id}"`,'primary')}</div>`:''}</div>`,{drawer:true});}
 function clientForm(id){const c=S().clients.find(c=>c.id===id)||{};open(id?'Edit client':'New client',`<form id="client-form" data-id="${id||''}"><div class="dialog-body">${field('Client or business name','name',c.name,'required maxlength="100"')}${field('Contact name','contact',c.contact,'required maxlength="100"')}${field('Email address','email',c.email,'type="email" required')}${field('Service or tag','tag',c.tag,'maxlength="60"')}<p class="hint">Issued invoices and published proposals keep their original client details.</p>${err}</div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">${id?'Save client':'Add client'}</button></div></form>`);}
 function editProject(id){const p=project(id);open('Edit project',`<form id="project-edit-form" data-id="${id}"><div class="dialog-body">${field('Project name','name',p.name,'required maxlength="100"')}${field('Service','service',p.service,'maxlength="80"')}${field('Target date','due',p.due,'type="date"')}<label class="field">Status<select name="status">${[...new Set([p.status,...(p.accepted?['active','completed','cancelled']:['inquiry','proposal','cancelled'])])].map(st=>`<option value="${st}" ${p.status===st?'selected':''}>${st[0].toUpperCase()+st.slice(1)}</option>`).join('')}</select></label>${note(p.accepted?'Scope, fees, phases, and payment terms are preserved in the accepted proposal.':'Edit the scope, fee, phases, and billing schedule in the proposal editor.')}${err}</div><div class="dialog-footer">${btn('Cancel','project',`data-id="${id}"`)}<button class="btn primary" type="submit">Save project</button></div></form>`);}
 function proposalDetail(id){const p=project(id);if(p.proposalStatus!=='draft')return proposalPreview(id,p.currentVersion,false);if(p.archived||p.status==='cancelled')return open('Proposal',`<div class="dialog-body">${note('Restore or reopen the project to edit its proposal.')}</div>`,{footer:btn('View project','project',`data-id="${id}"`)});
  phaseIds=p.phases.map(f=>f.id);const rules=p.billingPlan.length?p.billingPlan:defaultPlan(300000,p.deposit,p.phases);
  open('Edit proposal',`<form id="proposal-form" data-id="${id}"><div class="dialog-body"><div class="detail-client">${esc(projectClient(S(),p).name)} ${badge('draft')}</div><h1>${esc(p.name)}</h1><label class="field">Scope of work<textarea name="scope" rows="4" required>${esc(p.proposal)}</textarea></label><label class="field">Deliverables<textarea name="deliverables" rows="3" placeholder="One deliverable per line">${esc(p.deliverables)}</textarea></label>${field('Project fee (USD)','budget',p.budget?p.budget/100:'','type="number" min="0.01" step="0.01" required')}<label class="field">Delivery phases<textarea name="phases" id="proposal-phases" rows="3" required>${p.phases.map(f=>esc(f.name)).join('\n')}</textarea></label><p class="hint">One phase per line. Update the payment triggers after changing phases.</p><div class="section-heading"><h3>Billing schedule</h3>${btn('Add payment','add-payment')}</div><div id="payment-rules">${rules.map((r,i)=>ruleRow(r,p.phases,i)).join('')}</div><div id="billing-summary" class="billing-summary" aria-live="polite"></div><p class="hint">Percentages must total 100%. Each milestone is invoiced once when approved.</p>${err}</div><div class="dialog-footer">${btn('Cancel','project',`data-id="${id}"`)}<button class="btn" type="submit" name="intent" value="save">Save draft</button><button class="btn primary" type="submit" name="intent" value="publish">Publish client preview</button></div></form>`,{drawer:true});updateSummary();
 }
 function ruleRow(r,phases,i){return `<div class="payment-rule" data-rule="${r.id||uid()}"><label class="field">Payment name<input name="rule-name" value="${esc(r.name)}" required maxlength="80"></label><label class="field">Percentage<input name="rule-percent" value="${r.percent}" type="number" min="0.01" max="100" step="0.01" required></label><label class="field trigger-field">Invoice trigger<select name="rule-phase" ${i===0?'disabled':''}>${i===0?'<option value="">Proposal accepted</option>':phases.map(f=>`<option value="${f.id}" ${r.phaseId===f.id?'selected':''}>${esc(f.name)} approved</option>`).join('')}</select></label>${i>0?`<button type="button" class="icon-btn remove-payment" data-action="remove-payment" aria-label="Remove ${esc(r.name)} payment">${icon('close')}</button>`:'<span class="rule-label">Deposit</span>'}</div>`;}
 function editorPhases(){const names=dialog.querySelector('[name=phases]').value.split('\n').map(x=>x.trim()).filter(Boolean);phaseIds=names.map((_,i)=>phaseIds[i]||uid());return names.map((name,i)=>({id:phaseIds[i],name}));}
 function refreshPhaseOptions(){const phases=editorPhases();dialog.querySelectorAll('.payment-rule select:not(:disabled)').forEach(el=>{const old=el.value;el.innerHTML=phases.map(f=>`<option value="${f.id}" ${f.id===old?'selected':''}>${esc(f.name)} approved</option>`).join('');});}
 function updateSummary(){const form=dialog.querySelector('#proposal-form');if(!form)return;const total=[...form.querySelectorAll('[name=rule-percent]')].reduce((a,el)=>a+Number(el.value||0),0);const budget=Math.round(Number(form.querySelector('[name=budget]').value)*100);const el=form.querySelector('#billing-summary');el.textContent=`${Math.round(total*100)/100}% allocated · Project fee ${money(budget||0)}`;el.classList.toggle('invalid',Math.abs(total-100)>0.00001);}
 function proposalPreview(id,number,client=true){
  const p=project(id),v=p.versions.find(v=>v.number===Number(number));if(!v)return open('Proposal',`<div class="dialog-body">${note('Publish a proposal before opening its client preview.')}</div>`,{footer:btn('Edit proposal','proposal',`data-id="${id}"`)});
  const actionable=v.number===p.currentVersion&&v.status==='published'&&!p.archived&&p.status!=='cancelled';
  const history=!client&&p.versions.length>1?`<section class="section"><h3>Version history</h3>${p.versions.map(x=>`<button class="list-line full-width" data-action="proposal-version" data-id="${id}" data-version="${x.number}"><span>Version ${x.number}</span>${badge(x.status)}</button>`).join('')}</section>`:'';
  open(client?'Client proposal preview':'Published proposal',`<div class="dialog-body"><div class="preview-role">${client?'CLIENT VIEW':'OWNER VIEW'} · VERSION ${v.number} ${badge(v.status)}</div><div class="document-preview"><div class="code-label">${esc(v.business)} / ${esc(v.client.name)}</div><h1>${esc(v.name)}</h1>${v.due?`<p class="muted">Target delivery: ${date(v.due)}</p>`:''}<h3>Scope</h3><p>${esc(v.scope)}</p>${v.deliverables?`<h3>Deliverables</h3><ul class="deliverables">${v.deliverables.split('\n').filter(Boolean).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<div class="list-line"><strong>Project fee</strong><strong>${money(v.budget)}</strong></div><section class="section"><h3>Billing schedule</h3>${schedule({...v},[])}</section><section class="section"><h3>Delivery phases</h3><p>${v.phases.map(f=>esc(f.name)).join(' → ')}</p></section></div><p class="hint">Prototype preview. Accepting records a sample agreement; no document is sent or legally signed.</p>${history}${err}</div>`,{drawer:true,footer:client?(actionable?btn('Decline','decline-preview',`data-id="${id}" data-version="${v.number}"`)+btn('Accept proposal (demo)','accept-version',`data-id="${id}" data-version="${v.number}"`,'accent'):btn('Back to project','project',`data-id="${id}"`)):(btn('Client preview','proposal-client',`data-id="${id}" data-version="${v.number}"`)+(!p.accepted&&!p.archived&&p.status!=='cancelled'?btn('Create revision','revise-proposal',`data-id="${id}"`):''))});
 }
 function approvePreview(id,phaseId){const p=project(id),f=p.phases.find(f=>f.id===phaseId),rules=p.billingPlan.filter(r=>r.phaseId===phaseId);const pending=rules.filter(r=>!S().invoices.some(i=>i.ruleId===r.id&&i.projectId===id));open('Approve milestone',`<div class="dialog-body"><h1>${esc(f.name)}</h1><p>Mark this phase approved and ${pending.length?`create ${pending.length===1?'an invoice':'invoices'} for ${money(pending.reduce((a,r)=>a+r.amount,0))}`:'keep its existing invoices'}. No email or payment request will be sent.</p>${err}</div>`,{footer:btn('Cancel','project',`data-id="${id}"`)+btn('Approve milestone','approve-milestone',`data-id="${id}" data-phase="${phaseId}"`,'accent')});}
 function intakeBuilder(){const f=S().intake;open('Inquiry form',`<form id="intake-builder"><div class="dialog-body">${field('Form title','title',f.title,'required maxlength="100"')}<label class="field">Introduction<textarea name="intro" rows="2">${esc(f.intro)}</textarea></label><div class="field-row">${field('Service','service',f.service,'required maxlength="80"')}${field('Tag for new inquiries','tag',f.tag,'required maxlength="60"')}</div><h3>Fields</h3><p class="hint">Name, contact email, project name, and scope are always required.</p><label class="check"><input name="collectBudget" type="checkbox" ${f.collectBudget?'checked':''}>Ask for an estimated budget (optional)</label><label class="check"><input name="collectDate" type="checkbox" ${f.collectDate?'checked':''}>Ask for a target date (optional)</label>${field('Additional question','question',f.question,'maxlength="160" placeholder="e.g. What is your main goal?"')}<label class="check"><input name="questionRequired" type="checkbox" ${f.questionRequired?'checked':''}>Require an answer to the additional question</label>${note('Preview and submit the form locally. Hosting a public form requires the server implementation.')}${err}</div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Save and preview</button></div></form>`);}
 function intakePreview(){const f=S().intake,key=uid();open('Client inquiry preview',`<form id="inquiry-form" data-key="${key}"><div class="dialog-body"><div class="preview-role">CLIENT VIEW · ${esc(S().settings.business)}</div><h1>${esc(f.title)}</h1><p>${esc(f.intro)}</p>${field('Your business or name','name','','required maxlength="100"')}${field('Contact name','contact','','required maxlength="100"')}${field('Email address','email','','type="email" required')}${field('Project name','project','','required maxlength="100"')}<label class="field">Project scope<textarea name="scope" rows="3" required></textarea></label>${f.collectBudget?field('Estimated budget (USD)','budget','','type="number" min="0.01" step="0.01"'):''}${f.collectDate?field('Target date','due','','type="date"'):''}${f.question?field(esc(f.question),'answer','',`${f.questionRequired?'required':''} maxlength="1000"`):''}<p class="hint">Submitting creates an inquiry in this browser. Existing clients are matched by email.</p>${err}</div><div class="dialog-footer">${btn('Edit form','intake-builder')}<button class="btn accent" type="submit">Submit inquiry (demo)</button></div></form>`,{drawer:true});}
 function portal(id='p1'){const p=project(id)||S().projects[0],c=projectClient(S(),p);open('Client portal preview',`<div class="dialog-body"><div class="preview-role">CLIENT VIEW · ${esc(S().settings.business)}</div><h1>${esc(p.name)}</h1><p>${esc(c.name)}</p><h3>Project status</h3>${badge(p.status)}<section class="section"><h3>Delivery phases</h3>${p.phases.map((f,i)=>`<div class="phase-row"><span class="phase-check ${f.done?'done':''}">${f.done?icon('check'):i+1}</span>${esc(f.name)}<small>${f.approved?'Approved':f.done?'Complete':'Upcoming'}</small></div>`).join('')}</section><section class="section"><h3>Proposal</h3>${p.currentVersion?btn('View proposal','proposal-client',`data-id="${p.id}" data-version="${p.currentVersion}"`):'<p class="muted">No published proposal.</p>'}</section><section class="section"><h3>Invoices</h3>${S().invoices.filter(i=>i.projectId===p.id).map(i=>`<div class="list-line"><span>${i.number} · ${money(i.amount)}</span>${badge(invoiceStatus(i))}</div>`).join('')||'<p class="muted">No invoices.</p>'}</section><p class="hint">Local preview only. Secure client access will be added with the server implementation.</p></div>`,{drawer:true});}
 function handleClick(a,el){const id=el.dataset.id;
  if(a==='edit-client')clientForm(id);
  else if(a==='archive-client'){const c=S().clients.find(c=>c.id===id);if(c.archived){archiveClient(S(),id);commit('Client restored.');clientDetail(id);}else open('Archive client?',`<div class="dialog-body"><p>Hide ${esc(c.name)} from the active client list. Existing projects, documents, and invoices remain available. You can restore this client later.</p></div>`,{footer:btn('Cancel','client',`data-id="${id}"`)+btn('Archive client','archive-client-confirm',`data-id="${id}"`)});}
  else if(a==='archive-client-confirm'){archiveClient(S(),id);commit('Client archived.');clientDetail(id);}
  else if(a==='edit-project')editProject(id);
  else if(a==='archive-project'){const p=project(id);if(p.archived){archiveProject(S(),id);commit('Project restored.');projectDetail(id);}else open('Archive project?',`<div class="dialog-body"><p>Hide ${esc(p.name)} from active project lists and pause its delivery actions. Existing invoices remain payable. You can restore it later.</p></div>`,{footer:btn('Cancel','project',`data-id="${id}"`)+btn('Archive project','archive-project-confirm',`data-id="${id}"`)});}
  else if(a==='archive-project-confirm'){archiveProject(S(),id);commit('Project archived.');projectDetail(id);}
  else if(a==='reopen-project'){reopenProject(S(),id);commit('Project reopened.');projectDetail(id);}
  else if(a==='proposal-client')proposalPreview(id,el.dataset.version,true);
  else if(a==='proposal-version')proposalPreview(id,el.dataset.version,false);
  else if(a==='revise-proposal'){reviseProposal(S(),id);commit('Previous published version withdrawn.');proposalDetail(id);}
  else if(a==='accept-version'){const invoice=acceptProposal(S(),id,el.dataset.version);commit(invoice?'Proposal accepted. Deposit invoice created.':'Proposal accepted. Create the deposit invoice manually while the workflow is paused.');projectDetail(id);}
  else if(a==='decline-preview')open('Decline proposal?',`<div class="dialog-body"><p>Mark this proposal declined. No invoice will be generated. The owner can prepare a revision.</p></div>`,{footer:btn('Back','proposal-client',`data-id="${id}" data-version="${el.dataset.version}"`)+btn('Decline proposal (demo)','decline-version',`data-id="${id}" data-version="${el.dataset.version}"`)});
  else if(a==='decline-version'){declineProposal(S(),id,el.dataset.version);commit('Proposal declined.');projectDetail(id);}
  else if(a==='approve-preview')approvePreview(id,el.dataset.phase);
  else if(a==='approve-milestone'){const bills=approveMilestone(S(),id,el.dataset.phase);commit(bills.length?'Milestone approved. Invoice is available in the billing schedule.':'Phase approved.');projectDetail(id);}
  else if(a==='complete-phase'){togglePhase(S(),id,el.dataset.phase);commit('Phase updated.');projectDetail(id);}
  else if(a==='add-payment'){refreshPhaseOptions();const phases=editorPhases(),count=dialog.querySelectorAll('.payment-rule').length;if(count>=9)throw Error('Up to eight milestone payments are supported.');dialog.querySelector('#payment-rules').insertAdjacentHTML('beforeend',ruleRow({name:'Milestone payment',percent:0,phaseId:phases.at(-1)?.id},phases,count));updateSummary();}
  else if(a==='remove-payment'){el.closest('.payment-rule').remove();updateSummary();}
  else if(a==='intake-builder')intakeBuilder();
  else if(a==='intake-preview')intakePreview();
  else return false;return true;
 }
 function handleSubmit(form,v,intent){const id=form.dataset.id;
  if(form.id==='client-form'){const c=saveClient(S(),v,id||undefined);commit(id?'Client updated.':'Client created.');clientDetail(c.id);}
  else if(form.id==='project-edit-form'){updateProject(S(),id,v);commit('Project updated.');projectDetail(id);}
  else if(form.id==='proposal-form'){const phases=editorPhases();const rules=[...form.querySelectorAll('.payment-rule')].map(row=>({id:row.dataset.rule,name:row.querySelector('[name=rule-name]').value,percent:Number(row.querySelector('[name=rule-percent]').value),phaseId:row.querySelector('[name=rule-phase]').value||null}));saveProposal(S(),id,{scope:v.scope,deliverables:v.deliverables,budget:Math.round(Number(v.budget)*100),phases:phases.map(f=>f.name),phaseIds:phases.map(f=>f.id),rules});if(intent==='publish'){const version=publishProposal(S(),id);commit('Client preview published.');proposalPreview(id,version.number,true);}else{commit('Proposal draft saved.');projectDetail(id);}}
  else if(form.id==='intake-builder'){saveIntake(S(),{...v,collectBudget:form.elements.collectBudget.checked,collectDate:form.elements.collectDate.checked,questionRequired:form.elements.questionRequired.checked});commit('Inquiry form saved.');intakePreview();}
  else if(form.id==='inquiry-form'){const p=submitInquiry(S(),{...v,budget:v.budget?Math.round(Number(v.budget)*100):''},form.dataset.key);commit('Inquiry received. Client and project linked.');projectDetail(p.id);}
  else return false;return true;
 }
 function handleInput(el){if(el.id==='proposal-phases')refreshPhaseOptions();if(el.closest('#proposal-form'))updateSummary();}
 return{projectDetail,clientDetail,clientForm,proposalDetail,portal,handleClick,handleSubmit,handleInput};
}
